cambios.texto_nuevo:
archivo = open(os.path.join(raiz, 'memoria', '.salida_tarea_' + str(orden.get('id', '')) + '.txt'), 'w', encoding='utf-8', errors='replace')
proceso = subprocess.Popen(
    comando,
    cwd=raiz,
    stdout=archivo,
    stderr=subprocess.STDOUT,
    env=entorno,
)

def avance():
    total = 0.0
    try:
        import psutil
        pp = psutil.Process(proceso.pid)
        for p in [pp] + pp.children(recursive=True):
            try:
                t = p.cpu_times()
                total += t.user + t.system
            except psutil.Error:
                pass
        total = round(total, 1)
    except Exception:
        pass
    try:
        total += os.path.getsize(archivo.name)
    except Exception:
        pass
    for nombre in ('CUADERNO_DE_LLAMADAS.jsonl', 'APLICACIONES.log'):
        try:
            total += os.path.getmtime(os.path.join(raiz, 'memoria', nombre))
        except Exception:
            pass
    return total

from cuerpo import vigilante
estado = vigilante.esperar(proceso, LIMITE_TAREA_SEGUNDOS, SIN_AVANCE_SEGUNDOS, TOPE_DURO_SEGUNDOS, avance)
archivo.close()
try:
    with open(archivo.name, 'r', encoding='utf-8', errors='replace') as f:
        salida = f.read()
except Exception:
    salida = ''
salida_normal, salida_errores = proceso.communicate()
if estado != 'termino':
    return {
        'guardado': False,
        'codigo': None,
        'salida': 'COLGADA: ' + estado + ' (sin avance pasado el limite; se busca la causa raiz)\n' + salida_normal + salida_errores,
    }
return {
    "guardado": "GUARDADO AL MOMENTO" in salida,
    "codigo": proceso.returncode,
    "salida": salida,
}

